insert into public.accounts(id,owner_id,name,kind,opening,cutoff) values('10000000-0000-4000-8000-000000000020','10000000-0000-4000-8000-000000000002','Conta privada','bank',100000,'2026-11-01');
insert into public.cards values('10000000-0000-4000-8000-000000000030','10000000-0000-4000-8000-000000000001','Compartilhado',5,15,array['10000000-0000-4000-8000-000000000002'::uuid]);
insert into public.entries(id,owner_id,family_id,description,kind,amount,occurred_on,category,consumer_id,card_id) values('10000000-0000-4000-8000-000000000040','10000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000010','Particular A','expense',35000,'2026-11-04','Outros','10000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000030'),('10000000-0000-4000-8000-000000000041','10000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000010','Particular B','expense',65000,'2026-11-04','Outros','10000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000030');
insert into public.plans(id,owner_id,description,first_due,count,amount,kind) values('10000000-0000-4000-8000-000000000050','10000000-0000-4000-8000-000000000002','Contrato privado','2026-03-20',10,20000,'loan');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
select is((select count(*) from public.accounts where id='10000000-0000-4000-8000-000000000020'),0::bigint,'Admin não lê conta privada B');
select is((select count(*) from public.plans where id='10000000-0000-4000-8000-000000000050'),0::bigint,'Admin não lê contrato privado B');
select is((select count(*) from public.entries where card_id='10000000-0000-4000-8000-000000000030'),2::bigint,'Titular lê compras integrais');
select ok(not has_table_privilege('authenticated','public.accounts','INSERT'),'INSERT direto negado');
select ok(not has_table_privilege('authenticated','public.accounts','UPDATE'),'UPDATE direto negado');
select ok(not has_table_privilege('authenticated','public.accounts','DELETE'),'DELETE direto negado');
select ok(not has_function_privilege('authenticated','private.account_balance(uuid)','EXECUTE'),'Helper não expõe saldo privado');
select throws_ok($$select public.identity_lookup('pessoa_b')$$,'42501','permission denied for function identity_lookup','Username privado não é enumerável');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',true);
select is((select count(*) from public.accounts where id='10000000-0000-4000-8000-000000000020'),1::bigint,'Dono lê sua conta');
select is((select count(*) from public.entries where card_id='10000000-0000-4000-8000-000000000030'),1::bigint,'Autorizado lê só suas compras');
select throws_ok($$update public.accounts set opening=0$$,'42501','permission denied for table accounts','API direta não altera saldo');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000003',true);
select is((select count(*) from public.entries where family_id='10000000-0000-4000-8000-000000000010'),0::bigint,'Estranho não lê Casa');
select is((select count(*) from public.cards where id='10000000-0000-4000-8000-000000000030'),0::bigint,'Estranho não lê cartão');
select is((select count(*) from public.accounts where id='10000000-0000-4000-8000-000000000020'),0::bigint,'Estranho não lê conta por ID');
select ok(not has_table_privilege('authenticated','public.audit_logs','DELETE'),'Auditoria não pode ser apagada');
select * from finish();
rollback;
